// Downloads one representative stock photo per group in photo-group-queries.csv
// (generated by generate-photo-groups.mjs) from the Pexels API, saved to
// public/recipes/groups/<group>.jpg. Run generate-photo-groups.mjs first.
//
// Requires PEXELS_API_KEY in .env.local (get a free key at pexels.com/api).
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));

function loadEnvLocal() {
  const envPath = path.join(root, ".env.local");
  if (!existsSync(envPath)) return;
  for (const line of readFileSync(envPath, "utf8").split("\n")) {
    const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2].trim();
  }
}
loadEnvLocal();

const API_KEY = process.env.PEXELS_API_KEY;
if (!API_KEY) {
  console.error("Missing PEXELS_API_KEY (set it in .env.local)");
  process.exit(1);
}

function parseCsv(text) {
  return text
    .trim()
    .split("\n")
    .map(line => line.match(/"((?:[^"]|"")*)"/g).map(f => f.slice(1, -1).replace(/""/g, '"')));
}

const [header, ...rows] = parseCsv(readFileSync(path.join(root, "photo-group-queries.csv"), "utf8"));
const groups = rows.map(r => Object.fromEntries(header.map((h, i) => [h, r[i]])));

const outDir = path.join(root, "public", "recipes", "groups");
mkdirSync(outDir, { recursive: true });

async function searchPhoto(query) {
  const url = `https://api.pexels.com/v1/search?query=${encodeURIComponent(query)}&per_page=3&orientation=landscape`;
  const res = await fetch(url, { headers: { Authorization: API_KEY } });
  if (!res.ok) throw new Error(`Pexels search failed (${res.status}) for "${query}": ${await res.text()}`);
  const data = await res.json();
  return data.photos?.[0] ?? null;
}

async function downloadTo(url, filePath) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Download failed (${res.status}) for ${url}`);
  const buf = Buffer.from(await res.arrayBuffer());
  writeFileSync(filePath, buf);
  return buf.length;
}

const results = [];
for (const { group, query, count } of groups) {
  const outFile = path.join(outDir, `${group}.jpg`);
  try {
    const photo = await searchPhoto(query);
    if (!photo) {
      console.warn(`No Pexels result for group "${group}" (query: "${query}")`);
      results.push({ group, query, count, status: "no-result" });
      continue;
    }
    const bytes = await downloadTo(photo.src.large, outFile);
    console.log(`${group} (${count} recipes) <- "${query}" -> ${photo.url} [${(bytes / 1024).toFixed(0)} KB]`);
    results.push({ group, query, count, status: "ok", photographer: photo.photographer, source: photo.url });
  } catch (err) {
    console.error(`FAILED ${group}: ${err.message}`);
    results.push({ group, query, count, status: "error", error: err.message });
  }
  // Pexels free tier: 200 req/hour - no need to throttle for 42 groups, but stay polite.
  await new Promise(r => setTimeout(r, 250));
}

writeFileSync(
  path.join(root, "photo-group-credits.json"),
  JSON.stringify(results, null, 2),
  "utf8"
);

const failed = results.filter(r => r.status !== "ok");
console.log(`\nDone: ${results.length - failed.length}/${results.length} photos saved to public/recipes/groups/`);
if (failed.length) {
  console.log(`Failed/missing: ${failed.map(f => f.group).join(", ")}`);
}
